<script>const w=document.querySelector('[data-case-code]');if(w){const b=[...w.querySelectorAll('input')],v=document.querySelector('[data-case-code-value]'),s=()=>v.value=b.map(i=>i.value).join('');b.forEach((x,n)=>x.addEventListener('input',()=>{x.value=x.value.replace(/\D/g,'').slice(-1);s();if(x.value)b[n+1]?.focus()}));w.closest('form').addEventListener('submit',s)}const m=document.querySelector('[data-termination-modal]');document.querySelector('[data-open-termination]')?.addEventListener('click',()=>m.showModal());document.querySelector('[data-cancel-termination]')?.addEventListener('click',()=>m.close());</script></body></html>
